const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-122.555169, 40.190004);
  const startDate = '2020-08-25';
  const endDate = '2020-08-26'; // End date is exclusive

  // 2. Data Acquisition
  const collection = ee.ImageCollection('MERRA-2/M2I1NXASM')
    .select('BCCMASS') // Black Carbon Column Mass Density in kg m-2
    .filterDate(startDate, endDate)
    .filterBounds(point);

  // 3. Data Availability Check
  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log(`Image Count for ${startDate}: 0`);
    console.log("No MERRA-2 images found for the specified date and location.");
    console.log('A'); // Fallback: Even if no MERRA-2 images, the value is not > 12 mg/m^2, so the answer is No.
    return;
  }
  console.log(`Image Count for ${startDate}: ${imageCount}`);

  // 4. Processing & Calculation
  // Calculate the daily mean from the hourly images.
  const dailyMeanImage = collection.mean();

  // MERRA-2 has a coarse resolution (approx 50km), so a large scale is appropriate.
  const scale = 1000; 

  const result = dailyMeanImage.reduceRegion({
    reducer: ee.Reducer.first(), // Use 'first' as it's a single value from the pixel.
    geometry: point,
    scale: scale,
    // No crs needed as we use a large scale on a global dataset
  }).get('BCCMASS');

  // Check for null result (C3) or no valid pixels (C2)
  const blackCarbonKg_m2 = result.getInfo();
  if (blackCarbonKg_m2 === null || blackCarbonKg_m2 === undefined) {
      console.log("Could not extract a valid pixel value at the location.");
      console.log("This can happen if the point is over an ocean area with no data in the model.");
      console.log('C2');
      return;
  }

  // Convert from kg/m^2 to mg/m^2 (1 kg = 1,000,000 mg)
  const blackCarbonMg_m2 = blackCarbonKg_m2 * 1e6;

  // 5. Validation & Final Answer
  const threshold = 12; // mg/m^2
  console.log(`Date: ${startDate}`);
  console.log(`Black Carbon Concentration (mg/m^2): ${blackCarbonMg_m2.toFixed(4)}`);
  console.log(`Threshold (mg/m^2): ${threshold}`);

  if (blackCarbonMg_m2 > threshold) {
    console.log("Result: Black carbon concentration was above the threshold.");
    console.log('A');
  } else {
    console.log("Result: Black carbon concentration was not above the threshold.");
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during execution.");
    console.error(err);
    console.log('D');
});
